package com.fuelflex.platform.operations.blocktwo;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import java.math.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fuelflex.platform.operations.entity.*;import com.fuelflex.platform.operations.repository.ShiftReconciliationRepository;import com.fuelflex.platform.operations.service.ShiftReconciliationService;import com.fuelflex.platform.sale.entity.SaleType;import com.fuelflex.platform.sale.repository.FuelSaleRepository;
class ShiftReconciliationServiceTest{
 @Test void separatesCashCreditAndPreservesPhysicalVariance(){ShiftReconciliationRepository repo=mock(ShiftReconciliationRepository.class);FuelSaleRepository sales=mock(FuelSaleRepository.class);PumpShiftAssignment shift=new PumpShiftAssignment();shift.setId(UUID.randomUUID());shift.setOpeningIndex(new BigDecimal("1000.000"));shift.setClosingIndex(new BigDecimal("1250.000"));when(sales.sumEffectiveQuantityByShiftAndType(shift.getId(),SaleType.CASH)).thenReturn(new BigDecimal("150.000"));when(sales.sumEffectiveQuantityByShiftAndType(shift.getId(),SaleType.CREDIT)).thenReturn(new BigDecimal("90.000"));when(repo.findByShiftAssignmentId(shift.getId())).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));ShiftReconciliation r=new ShiftReconciliationService(repo,sales).calculate(shift);assertThat(r.getMeteredVolume()).isEqualByComparingTo("250.000");assertThat(r.getTotalSoldVolume()).isEqualByComparingTo("240.000");assertThat(r.getVolumeVariance()).isEqualByComparingTo("10.000");}
}
